product:
from math import prod

def solve(data, key):
    return prod(data)

xor_reduce:
from functools import reduce
from operator import xor

def solve(data, key):
    return reduce(xor, data, 0)

gcd:
from math import gcd

def solve(data, key):
    return gcd(*data[:2]) if len(data) >= 2 else 0

factorial:
from math import factorial

def solve(data, key):
    return factorial(key)

fibonacci:
def solve(data, key):
    a, b = 0, 1
    for _ in range(key):
        a, b = b, a + b
    return a

reverse:
def solve(data, key):
    data.reverse()
    return len(data)

sort:
def solve(data, key):
    data.sort()
    return len(data)
